package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.*;import net.minecraft.core.BlockPos;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;public class SoulSoilConduitBlock extends Block{public SoulSoilConduitBlock(Properties p){super(p);}@Override public MapCodec<SoulSoilConduitBlock> codec(){return RedstoneEngineering.SOUL_SOIL_CONDUIT_CODEC.value();}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Soul Flux conduit J≈"+SoulFluxNetwork.charge(l,p)+" | Minecraft-fictional physics"),true);return InteractionResult.sidedSuccess(l.isClientSide);}}